const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { execSync } = require('child_process');

const ROOT_DIR = path.resolve(__dirname, '../../..');
const DEP_MAP_PATH = path.join(ROOT_DIR, 'ChatMachines/GeminiSupervisor/dependency-map.json');

function getGitBlobSha(filePath) {
  try {
    return execSync(`git hash-object "${filePath}"`, { encoding: 'utf8', cwd: ROOT_DIR }).trim();
  } catch (err) {
    const fileBuffer = fs.readFileSync(filePath);
    const header = Buffer.from(`blob ${fileBuffer.length}\0`);
    return crypto.createHash('sha1').update(Buffer.concat([header, fileBuffer])).digest('hex');
  }
}

function getHeadCommitSha() {
  try {
    return execSync('git rev-parse HEAD', { encoding: 'utf8', cwd: ROOT_DIR }).trim();
  } catch (err) {
    return 'HEAD_UNKNOWN';
  }
}

function parseMarkdownToRecords(content) {
  const lines = content.split(/\r?\n/);
  const records = [];
  let currentTopic = null;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const headingMatch = line.match(/^(#{1,6})\s+(.+)$/);
    if (headingMatch) {
      currentTopic = headingMatch[2].trim();
    }
    records.push({
      index: i,
      topic: currentTopic,
      text: line
    });
  }
  return records;
}

function parseJsonToRecords(content) {
  const parsed = JSON.parse(content);
  if (Array.isArray(parsed)) {
    return parsed.map((item, idx) => ({
      index: idx,
      topic: `item_${idx}`,
      value: item
    }));
  } else if (typeof parsed === 'object' && parsed !== null) {
    const keys = Object.keys(parsed);
    return keys.map((key, idx) => ({
      index: idx,
      topic: key,
      value: parsed[key]
    }));
  }
  return [{ index: 0, topic: 'scalar', value: parsed }];
}

function syncAll() {
  if (!fs.existsSync(DEP_MAP_PATH)) {
    console.error(`Dependency map not found at ${DEP_MAP_PATH}`);
    process.exit(1);
  }

  const depMap = JSON.parse(fs.readFileSync(DEP_MAP_PATH, 'utf8'));
  const commitSha = getHeadCommitSha();
  let updated = false;

  for (const [docKey, entry] of Object.entries(depMap.mappings)) {
    const canonicalFullPath = path.join(ROOT_DIR, entry.canonical_path);
    const readerFullPath = path.join(ROOT_DIR, entry.stable_reader_path);

    if (!fs.existsSync(canonicalFullPath)) {
      console.warn(`Canonical source missing: ${entry.canonical_path}`);
      continue;
    }

    const currentSourceBlob = getGitBlobSha(canonicalFullPath);
    const rawContent = fs.readFileSync(canonicalFullPath, 'utf8');
    const isJson = entry.canonical_path.endsWith('.json');
    const records = isJson ? parseJsonToRecords(rawContent) : parseMarkdownToRecords(rawContent);

    const projection = {
      doc_id: docKey,
      canonical_path: entry.canonical_path,
      source_blob_sha: currentSourceBlob,
      item_count: records.length,
      generated_at: new Date().toISOString(),
      records: records
    };

    const projectionJson = JSON.stringify(projection, null, 2);
    fs.mkdirSync(path.dirname(readerFullPath), { recursive: true });
    fs.writeFileSync(readerFullPath, projectionJson, 'utf8');

    const currentReaderBlob = getGitBlobSha(readerFullPath);
    if (entry.source_blob_sha !== currentSourceBlob || entry.reader_blob_sha !== currentReaderBlob) {
      entry.source_blob_sha = currentSourceBlob;
      entry.source_commit_sha = commitSha;
      entry.reader_blob_sha = currentReaderBlob;
      entry.item_count = records.length;
      entry.last_synced_at = new Date().toISOString();
      updated = true;
    }
  }

  if (updated) {
    fs.writeFileSync(DEP_MAP_PATH, JSON.stringify(depMap, null, 2) + '\n', 'utf8');
    const sentinelPath = path.join(ROOT_DIR, depMap.sentinel_file);
    fs.mkdirSync(path.dirname(sentinelPath), { recursive: true });
    fs.writeFileSync(sentinelPath, `SYNCED=${new Date().toISOString()}\nCOMMIT=${commitSha}\n`, 'utf8');
    console.log('Successfully synced stable readers and updated dependency map.');
  } else {
    console.log('All readers are up-to-date.');
  }
}

if (require.main === module) {
  syncAll();
}

module.exports = { syncAll, parseMarkdownToRecords, parseJsonToRecords };

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const assert = require('assert');

const ROOT_DIR = path.resolve(__dirname, '../../..');
const DEP_MAP_PATH = path.join(ROOT_DIR, 'ChatMachines/GeminiSupervisor/dependency-map.json');
const PLACEHOLDER_KEY = '^MISSING_KEY^';
const PLACEHOLDER_VALUE = '^MISSING_VALUE^';

function secureRandomInt(min, max) {
  const range = max - min;
  if (range <= 0) return min;
  const randomBuffer = crypto.randomBytes(4);
  const randomValue = randomBuffer.readUInt32BE(0);
  return min + (randomValue % range);
}

function selectDistributedIndices(totalCount, damageRate = 0.1) {
  const targetDamageCount = Math.max(1, Math.round(totalCount * damageRate));
  const bandCount = Math.min(targetDamageCount, Math.floor(totalCount / 3) || 1);
  const bandSize = totalCount / bandCount;
  const selected = new Set();

  for (let b = 0; b < bandCount; b++) {
    const start = Math.floor(b * bandSize);
    const end = Math.floor((b + 1) * bandSize);
    const picked = secureRandomInt(start, end);
    selected.add(picked);
  }

  while (selected.size < targetDamageCount && selected.size < totalCount) {
    const idx = secureRandomInt(0, totalCount);
    selected.add(idx);
  }
  return Array.from(selected).sort((a, b) => a - b);
}

function createDamagedProjection(intactProjection, runNonce) {
  const damaged = JSON.parse(JSON.stringify(intactProjection));
  damaged.run_nonce = runNonce;
  damaged.challenge_type = 'repair_required';
  damaged.placeholder_marker = { key: PLACEHOLDER_KEY, value: PLACEHOLDER_VALUE };

  const records = damaged.records;
  const damagedIndices = selectDistributedIndices(records.length, 0.10);

  for (const idx of damagedIndices) {
    records[idx] = {
      index: idx,
      topic: PLACEHOLDER_KEY,
      damaged: true,
      text: PLACEHOLDER_VALUE,
      value: PLACEHOLDER_VALUE
    };
  }

  damaged.damaged_indices_count = damagedIndices.length;
  return { damaged, damagedIndices };
}

function initializeRunChallenges(runNonce, selectedDocIds) {
  if (!fs.existsSync(DEP_MAP_PATH)) {
    throw new Error(`Dependency map not found: ${DEP_MAP_PATH}`);
  }
  const depMap = JSON.parse(fs.readFileSync(DEP_MAP_PATH, 'utf8'));
  const runDir = path.join(ROOT_DIR, 'ChatMachines/GeminiSupervisor/runs', runNonce);
  const truthDir = path.join(runDir, 'truth-reader');
  const baselineDir = path.join(truthDir, '.baseline');

  fs.mkdirSync(truthDir, { recursive: true });
  fs.mkdirSync(baselineDir, { recursive: true });

  const manifest = {
    run_nonce: runNonce,
    created_at: new Date().toISOString(),
    status: 'PENDING_WORKER_REPAIR',
    documents: {}
  };

  for (const docId of selectedDocIds) {
    const mapping = depMap.mappings[docId];
    if (!mapping) {
      throw new Error(`Unrecognized document selector: ${docId}`);
    }
    const stableReaderFullPath = path.join(ROOT_DIR, mapping.stable_reader_path);
    if (!fs.existsSync(stableReaderFullPath)) {
      throw new Error(`Stable reader not found at: ${stableReaderFullPath}`);
    }

    const stableReader = JSON.parse(fs.readFileSync(stableReaderFullPath, 'utf8'));
    const fullProjection = JSON.parse(JSON.stringify(stableReader));
    fullProjection.run_nonce = runNonce;
    fullProjection.provenance = {
      canonical_path: mapping.canonical_path,
      source_blob_sha: mapping.source_blob_sha,
      source_commit_sha: mapping.source_commit_sha,
      reader_blob_sha: mapping.reader_blob_sha,
      last_synced_at: mapping.last_synced_at
    };

    const { damaged } = createDamagedProjection(fullProjection, runNonce);

    const fullDocPath = path.join(truthDir, `${docId}.full.json`);
    const repairDocPath = path.join(truthDir, `${docId}.repair.json`);
    const baselineDocPath = path.join(baselineDir, `${docId}.damaged.json`);

    fs.writeFileSync(fullDocPath, JSON.stringify(fullProjection, null, 2), 'utf8');
    fs.writeFileSync(repairDocPath, JSON.stringify(damaged, null, 2), 'utf8');
    fs.writeFileSync(baselineDocPath, JSON.stringify(damaged, null, 2), 'utf8');

    manifest.documents[docId] = {
      full_path: path.relative(ROOT_DIR, fullDocPath),
      repair_path: path.relative(ROOT_DIR, repairDocPath),
      item_count: fullProjection.records.length,
      damaged_count: damaged.damaged_indices_count
    };
  }

  fs.writeFileSync(path.join(truthDir, 'manifest.json'), JSON.stringify(manifest, null, 2), 'utf8');
  return manifest;
}

function containsGenericPlaceholders(obj) {
  const str = JSON.stringify(obj);
  return str.includes(PLACEHOLDER_KEY) || str.includes(PLACEHOLDER_VALUE);
}

function normalizeForComparison(obj) {
  const clone = JSON.parse(JSON.stringify(obj));
  delete clone.challenge_type;
  delete clone.placeholder_marker;
  delete clone.damaged_indices_count;
  if (Array.isArray(clone.records)) {
    for (const r of clone.records) {
      delete r.damaged;
    }
  }
  return clone;
}

function verifyRunRepairs(runNonce) {
  const truthDir = path.join(ROOT_DIR, 'ChatMachines/GeminiSupervisor/runs', runNonce, 'truth-reader');
  const baselineDir = path.join(truthDir, '.baseline');
  const manifestPath = path.join(truthDir, 'manifest.json');

  if (!fs.existsSync(manifestPath)) {
    throw new Error(`Truth reader manifest not found for run ${runNonce}`);
  }

  const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
  const results = { pass: true, mismatches: [] };

  for (const [docId, meta] of Object.entries(manifest.documents)) {
    const fullDocPath = path.join(truthDir, `${docId}.full.json`);
    const repairDocPath = path.join(truthDir, `${docId}.repair.json`);
    const baselineDocPath = path.join(baselineDir, `${docId}.damaged.json`);

    if (!fs.existsSync(repairDocPath)) {
      results.pass = false;
      results.mismatches.push(`${docId}: repair file missing`);
      continue;
    }

    let fullContent, repairContent;
    try {
      fullContent = JSON.parse(fs.readFileSync(fullDocPath, 'utf8'));
      repairContent = JSON.parse(fs.readFileSync(repairDocPath, 'utf8'));
    } catch (e) {
      results.pass = false;
      results.mismatches.push(`${docId}: parse error in repair JSON`);
      continue;
    }

    if (containsGenericPlaceholders(repairContent)) {
      results.pass = false;
      results.mismatches.push(`${docId}: generic placeholders still present`);
      continue;
    }

    const normFull = normalizeForComparison(fullContent);
    const normRepair = normalizeForComparison(repairContent);

    try {
      assert.deepStrictEqual(normRepair, normFull);
    } catch (err) {
      results.pass = false;
      results.mismatches.push(`${docId}: repaired content does not match intact projection`);
      if (fs.existsSync(baselineDocPath)) {
        fs.copyFileSync(baselineDocPath, repairDocPath);
      }
    }
  }

  if (results.pass) {
    const passRecord = {
      run_nonce: runNonce,
      verified_at: new Date().toISOString(),
      status: 'PASS',
      verified_documents: Object.keys(manifest.documents)
    };
    fs.writeFileSync(path.join(truthDir, 'PASS.json'), JSON.stringify(passRecord, null, 2), 'utf8');
    if (fs.existsSync(baselineDir)) {
      fs.rmSync(baselineDir, { recursive: true, force: true });
    }
    for (const docId of Object.keys(manifest.documents)) {
      const repairPath = path.join(truthDir, `${docId}.repair.json`);
      if (fs.existsSync(repairPath)) {
        fs.unlinkSync(repairPath);
      }
    }
    manifest.status = 'COMPLETED_PASS';
    manifest.verified_at = passRecord.verified_at;
    fs.writeFileSync(manifestPath, JSON.stringify(manifest, null, 2), 'utf8');
    return { success: true, passRecord };
  } else {
    return { success: false, errors: results.mismatches };
  }
}

module.exports = {
  selectDistributedIndices,
  createDamagedProjection,
  initializeRunChallenges,
  verifyRunRepairs,
  normalizeForComparison
};

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const ROOT_DIR = path.resolve(__dirname, '../../..');
const DEP_MAP_PATH = path.join(ROOT_DIR, 'ChatMachines/GeminiSupervisor/dependency-map.json');

function generateStep0Form(userRequest, existingNonce = null) {
  const runNonce = existingNonce || crypto.randomBytes(8).toString('hex');
  const depMap = JSON.parse(fs.readFileSync(DEP_MAP_PATH, 'utf8'));

  const selectableDocs = {};
  for (const docKey of Object.keys(depMap.mappings)) {
    selectableDocs[docKey] = false;
  }

  const form = {
    system_locked: {
      step_number: 0,
      role: 'Worker',
      run_nonce: runNonce,
      verbatim_user_request: userRequest || '',
      form_generated_at: new Date().toISOString(),
      selectable_document_universe: Object.keys(depMap.mappings)
    },
    worker_editable: {
      task_understanding: '',
      execution_plan: '',
      document_selection: selectableDocs
    },
    form_status: 'AWAITING_WORKER_INPUT'
  };

  const runDir = path.join(ROOT_DIR, 'ChatMachines/GeminiSupervisor/runs', runNonce);
  fs.mkdirSync(runDir, { recursive: true });
  const formPath = path.join(runDir, 'step-0-form.json');
  fs.writeFileSync(formPath, JSON.stringify(form, null, 2), 'utf8');

  return { runNonce, formPath, form };
}

if (require.main === module) {
  const userReq = process.argv[2] || 'Default maintenance run';
  const nonce = process.argv[3] || null;
  const res = generateStep0Form(userReq, nonce);
  console.log(`Generated Step 0 form for run ${res.runNonce} at ${res.formPath}`);
}

module.exports = { generateStep0Form };

name: Truth Reader Repair Gate

on:
  push:
    paths:
      - 'ChatMachines/GeminiSupervisor/runs/**'
      - 'ChatMachines/GeminiSupervisor/dependency-map.json'

permissions:
  contents: write

jobs:
  truth-reader-gate:
    runs-on: ubuntu-latest
    if: github.actor != 'github-actions[bot]' && !contains(github.event.head_commit.message, '[skip-truth-loop]')
    steps:
      - name: Checkout Repository
        uses: actions/checkout@v4
        with:
          fetch-depth: 0
          token: ${{ secrets.GITHUB_TOKEN }}

      - name: Setup Node.js
        uses: actions/setup-node@v4
        with:
          node-version: '20'

      - name: Process Runs and Truth Gates
        id: run-truth
        run: |
          node -e "
          const fs = require('fs');
          const path = require('path');
          const { initializeRunChallenges, verifyRunRepairs } = require('./ChatMachines/GeminiSupervisor/scripts/truth-challenge-engine.js');

          const runsRoot = path.join(process.cwd(), 'ChatMachines/GeminiSupervisor/runs');
          if (!fs.existsSync(runsRoot)) {
            console.log('No runs directory found.');
            process.exit(0);
          }

          const runDirs = fs.readdirSync(runsRoot, { withFileTypes: true }).filter(d => d.isDirectory()).map(d => d.name);
          let stateChanged = false;

          for (const nonce of runDirs) {
            const runPath = path.join(runsRoot, nonce);
            const formPath = path.join(runPath, 'step-0-form.json');
            const truthDir = path.join(runPath, 'truth-reader');
            const passPath = path.join(truthDir, 'PASS.json');
            const manifestPath = path.join(truthDir, 'manifest.json');

            if (fs.existsSync(passPath)) {
              continue;
            }

            if (fs.existsSync(formPath) && !fs.existsSync(manifestPath)) {
              const form = JSON.parse(fs.readFileSync(formPath, 'utf8'));
              const selections = form.worker_editable?.document_selection || {};
              const selectedDocs = Object.keys(selections).filter(k => selections[k] === true);
              if (selectedDocs.length > 0) {
                console.log('Initializing truth challenges for nonce: ' + nonce + ' with docs: ' + selectedDocs.join(', '));
                initializeRunChallenges(nonce, selectedDocs);
                stateChanged = true;
              }
            } else if (fs.existsSync(manifestPath)) {
              console.log('Verifying truth repairs for nonce: ' + nonce);
              const res = verifyRunRepairs(nonce);
              if (res.success) {
                console.log('PASS confirmed for run: ' + nonce);
                stateChanged = true;
              } else {
                console.log('Repair verification FAILED for run: ' + nonce + ' - ' + JSON.stringify(res.errors));
                stateChanged = true;
              }
            }
          }
          fs.writeFileSync('truth_changed.flag', stateChanged ? 'true' : 'false');
          "

      - name: Commit and Push Truth Gate Updates
        run: |
          CHANGED=$(cat truth_changed.flag || echo 'false')
          if [ "$CHANGED" = "true" ]; then
            git config user.name "github-actions[bot]"
            git config user.email "github-actions[bot]@users.noreply.github.com"
            git add ChatMachines/GeminiSupervisor/runs/
            if ! git diff --cached --quiet; then
              git commit -m "chore(truth-reader): process run challenges and repairs [skip-truth-loop]"
              git push
            fi
          else
            echo "No truth reader state mutations."
          fi
